"""Shared helpers for the thesis citation checker scripts."""
from __future__ import annotations

import csv
import hashlib
import json
import re
import sys
import unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CONFIG = ROOT / "config.json"

# Generated by the scripts (never edit by hand)
EXTRACTED = ROOT / "extracted"
PAPER_TEXT = EXTRACTED / "papers"                 # extracted/papers/<key>.txt
PAPERS_MANIFEST = EXTRACTED / "papers.json"       # key -> PDF location, pages, scanned...
THESIS_MD = EXTRACTED / "thesis.md"
DETECTED = EXTRACTED / "detected_citations.csv"
STRUCTURE = EXTRACTED / "thesis_structure.json"

# Your working data
CLAIMS = ROOT / "claims" / "claims.csv"
PAPER_INDEX = ROOT / "claims" / "papers.csv"      # key, file, folder, authors, year, title
REVIEW = ROOT / "claims" / "review.json"
RESULTS = ROOT / "results"
REPORTS = ROOT / "reports"

CLAIM_COLUMNS = [
    "id", "section", "paragraph", "paper_key", "claim",
    "citation_in_thesis", "cited_page", "type", "multiple_citation", "context",
]
INDEX_COLUMNS = ["key", "file", "folder", "authors", "year", "title"]
CLAIM_TYPES = {"paraphrase", "direct_quote", "data"}
VERDICTS = ["correct", "partial", "misrepresented", "not_found", "unverifiable"]
SEVERITIES = ["none", "minor", "moderate", "major"]
ERROR_TYPES = [
    "causality", "overgeneralization", "overstatement", "wrong_data", "missing_nuance",
    "secondary_citation", "misattribution", "inexact_quote", "contradicts", "not_present",
]
LANGUAGES = ("en", "es")
DEFAULTS = {"language": "en", "papers_dir": "papers", "thesis_dir": "thesis", "thesis_main": ""}

PAGE_MARKER = re.compile(r"^=== \[p\. (\d+)\] ===$", re.M)

# Windows consoles: force UTF-8 so accented characters never crash a script.
for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8")
    except Exception:
        pass


# ---------------------------------------------------------------- configuration

def load_config() -> dict:
    """Project settings: language, papers_dir, thesis_dir, thesis_main."""
    config = dict(DEFAULTS)
    try:
        config.update(json.loads(CONFIG.read_text(encoding="utf-8")))
    except (FileNotFoundError, json.JSONDecodeError):
        pass
    if config.get("language") not in LANGUAGES:
        config["language"] = "en"
    return config


def save_config(config: dict) -> None:
    write_json(CONFIG, {k: config.get(k, v) for k, v in DEFAULTS.items()})


def _resolve(value: str, default: str) -> Path:
    p = Path(value or default).expanduser()
    return p if p.is_absolute() else (ROOT / p).resolve()


def papers_dir() -> Path:
    """Folder with the PDFs. Subfolders are scanned too. Can live anywhere on disk."""
    return _resolve(load_config()["papers_dir"], "papers")


def thesis_dir() -> Path:
    """Folder with the thesis (a LaTeX project or a .docx/.md/.txt file). Can live anywhere on disk."""
    return _resolve(load_config()["thesis_dir"], "thesis")


# ---------------------------------------------------------------- papers

def slug(text: str, limit: int = 60) -> str:
    """'Smith et al. 2020 - Remote Work.pdf' stem -> 'smith_et_al_2020_remote_work'."""
    t = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode()
    t = re.sub(r"[^a-z0-9]+", "_", t.lower()).strip("_")
    return (t[:limit].rstrip("_") or "paper")


def file_hash(path: Path) -> str:
    h = hashlib.sha1()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def list_pdfs(folder: Path | None = None) -> list[dict]:
    """Every PDF under the papers folder (recursively), with a key that does not depend on where it lives.

    The key is a slug of the file name. Byte-identical copies of a PDF count as one paper (the
    first path wins, the others are listed in `duplicates`). Different PDFs that share a file name
    get a short fingerprint of their content appended, so moving files or picking another root
    folder never changes a key.
    """
    folder = folder or papers_dir()
    if not folder.is_dir():
        return []
    files = sorted((p for p in folder.rglob("*") if p.is_file() and p.suffix.lower() == ".pdf"
                    and not any(part.startswith(".") for part in p.relative_to(folder).parts)),
                   key=lambda p: str(p.relative_to(folder)).lower())
    by_name: dict[str, list[Path]] = {}
    for p in files:
        by_name.setdefault(slug(p.stem), []).append(p)

    out = []
    for base, paths in by_name.items():
        groups: dict[str, list[Path]] = {}
        for p in paths:
            groups.setdefault(file_hash(p) if len(paths) > 1 else "", []).append(p)
        for digest, same in groups.items():
            key = base if len(groups) == 1 else f"{base}_{digest[:6]}"
            p, rel = same[0], same[0].relative_to(folder)
            out.append({"key": key, "path": p, "file": rel.as_posix(),
                        "folder": rel.parent.as_posix() if rel.parent.as_posix() != "." else "",
                        "duplicates": [d.relative_to(folder).as_posix() for d in same[1:]]})
    return sorted(out, key=lambda e: e["file"].lower())


def read_manifest() -> dict[str, dict]:
    try:
        return {m["key"]: m for m in json.loads(PAPERS_MANIFEST.read_text(encoding="utf-8"))}
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def pdf_keys() -> set[str]:
    """Keys of the papers that have an extracted text (i.e. a PDF that was found)."""
    return {k for k in read_manifest() if (PAPER_TEXT / f"{k}.txt").exists()}


def pdf_path(key: str) -> Path | None:
    entry = read_manifest().get(key)
    if not entry:
        return None
    path = papers_dir() / entry["file"]
    return path if path.is_file() else None


# ---------------------------------------------------------------- text helpers

def normalize(text: str) -> str:
    """Normalize text so a quote can be compared with the PDF text.

    Joins words hyphenated across line breaks, unifies quotes, dashes and ligatures,
    collapses whitespace and lowercases.
    """
    t = unicodedata.normalize("NFKC", text)
    t = re.sub(r"(\w)[-­]\s*\n\s*(\w)", r"\1\2", t)
    t = t.replace("­", "")
    t = re.sub(r"[‘’‚‛′`´]", "'", t)
    t = re.sub(r"[“”„‟″«»]", '"', t)
    t = re.sub(r"[‐-―−]", "-", t)
    t = t.replace("…", "...")
    t = re.sub(r"\s+", " ", t)
    return t.strip().lower()


def read_pages(key: str) -> list[tuple[int, str]]:
    """Return [(page_number, text)] for a paper's extracted text."""
    path = PAPER_TEXT / f"{key}.txt"
    if not path.exists():
        return []
    parts = PAGE_MARKER.split(path.read_text(encoding="utf-8"))
    # parts = [preamble, n1, text1, n2, text2, ...]
    return [(int(parts[i]), parts[i + 1]) for i in range(1, len(parts) - 1, 2)]


# ---------------------------------------------------------------- data files

def read_csv(path: Path) -> list[dict]:
    if not path.exists():
        return []
    with path.open(encoding="utf-8-sig", newline="") as f:
        return [dict(row) for row in csv.DictReader(f)]


def read_claims() -> list[dict]:
    return read_csv(CLAIMS)


def read_result(key: str) -> dict | None:
    path = RESULTS / f"{key}.json"
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        print(f"[!] {path.name} is not valid JSON: {e}", file=sys.stderr)
        return None


def read_json(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError):
        return default


def read_review() -> dict:
    return read_json(REVIEW, {})


def write_json(path: Path, data) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
